findings.remediation:
Override the `burn` and `burnFrom` functions from `ERC20Burnable` and have them revert with an error message, directing users to use the official withdrawal process. This ensures that tokens can only be burned through the intended `burnForWithdrawal` flow.

solidity
// In INRT contract
function burn(uint256 amount) public override {
    revert("INRT: Direct burn not supported. Use the withdrawal process.");
}

function burnFrom(address account, uint256 amount) public override {
    revert("INRT: Direct burn not supported. Use the withdrawal process.");
}

To increase security and user trust, make the `inrtToken` address immutable by setting it only once in the constructor. If mutability is a requirement, implement a timelock for changing critical addresses to allow users time to react to changes.

solidity
// In CryptoUPIHook contract

contract CryptoUPIHook is Ownable {
    IINRT public immutable inrtToken;

    constructor(address _inrtToken) {
        require(_inrtToken != address(0), "CryptoUPIHook: Address cannot be zero");
        inrtToken = IINRT(_inrtToken);
    }

    // ... remove setInrtToken function
}

Add an event to the `CryptoUPIHook` contract and emit it within the `setInrtToken` function to log this critical change.

solidity
// In CryptoUPIHook contract
event InrtTokenSet(address indexed oldToken, address indexed newToken);

function setInrtToken(address _inrtToken) public onlyOwner {
    require(_inrtToken != address(0), "CryptoUPIHook: Address cannot be zero");
    emit InrtTokenSet(address(inrtToken), _inrtToken);
    inrtToken = IINRT(_inrtToken);
}
